class Solution { public List<Integer> largestValues(TreeNode root){List<Integer> answer=new ArrayList<>();if(root==null)return answer;Queue<TreeNode> queue=new ArrayDeque<>();queue.offer(root);while(!queue.isEmpty()){int maximum=Integer.MIN_VALUE;for(int size=queue.size();size>0;size--){TreeNode node=queue.poll();maximum=Math.max(maximum,node.val);if(node.left!=null)queue.offer(node.left);if(node.right!=null)queue.offer(node.right);}answer.add(maximum);}return answer;} }
